create table if not exists public.ai_agents(agent_id bigint generated always as identity primary key,agent_name text not null unique,system_prompt text not null,model_version text not null,is_active boolean not null default true);
create table if not exists public.ai_prompt(prompt_id bigint generated always as identity primary key,agent_id bigint not null references public.ai_agents(agent_id) on delete cascade,prompt_name text not null,prompt_text text not null,module_target text not null,unique(agent_id,prompt_name));
create table if not exists public.ai_conversation(conversation_id bigint generated always as identity primary key,user_id bigint not null references public.users(user_id),agent_id bigint not null references public.ai_agents(agent_id),started_at timestamptz not null default now());
create table if not exists public.ai_document(ai_doc_id bigint generated always as identity primary key,document_id bigint not null references public.documents(document_id) on delete cascade,extracted_data_json text not null,confidence_score numeric(7,4) not null check(confidence_score between 0 and 100));
create table if not exists public.ai_prediction(prediction_id bigint generated always as identity primary key,subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),prediction_type text not null,target_entity_id bigint not null,value_predicted numeric(24,6) not null,confidence numeric(7,4) not null check(confidence between 0 and 100),execution_date date not null);
do $$declare t text;begin foreach t in array array['ai_agents','ai_prompt','ai_conversation','ai_document','ai_prediction'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "ai_select" on public.%I',t);execute format('drop policy if exists "ai_insert" on public.%I',t);execute format('drop policy if exists "ai_update" on public.%I',t);execute format('drop policy if exists "ai_delete" on public.%I',t);execute format('create policy "ai_select" on public.%I for select to authenticated using(true)',t);execute format('create policy "ai_insert" on public.%I for insert to authenticated with check(true)',t);execute format('create policy "ai_update" on public.%I for update to authenticated using(true) with check(true)',t);execute format('create policy "ai_delete" on public.%I for delete to authenticated using(true)',t);end loop;end$$;
